use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::BTreeMap;
use std::io::{self, BufWriter, Write};

const BILLING_UNIT_SECONDS: i64 = 900;
const MINIMUM_ENTRY_SECONDS: i64 = 1800;

pub struct InvoiceMonthlyCommand;

fn invoice_seconds(duration: i64) -> i64 {
    let duration = duration.max(0);
    let rounded = (duration / BILLING_UNIT_SECONDS
        + i64::from(duration % BILLING_UNIT_SECONDS != 0))
        * BILLING_UNIT_SECONDS;
    rounded.max(MINIMUM_ENTRY_SECONDS)
}

fn monthly_totals(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();

    for entry in entries {
        if !entry.billable || entry.stop.is_none() {
            continue;
        }

        let month = entry.start.format("%Y-%m").to_string();
        *totals.entry(month).or_default() += invoice_seconds(entry.duration);
    }

    totals
}

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let totals = monthly_totals(&entries);

        let stdout = io::stdout();
        let mut handle = BufWriter::new(stdout);
        if totals.is_empty() {
            writeln!(handle, "(no data)").expect("failed to print");
            return Ok(());
        }

        let mut total = 0;
        for (month, seconds) in totals {
            writeln!(handle, "{month}  {seconds}s").expect("failed to print");
            total += seconds;
        }
        writeln!(handle, "Total  {total}s").expect("failed to print");
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::{invoice_seconds, monthly_totals};
    use crate::models::TimeEntry;
    use chrono::{TimeZone, Utc};

    fn entry(start: &str, duration: i64, billable: bool, stopped: bool) -> TimeEntry {
        TimeEntry {
            id: duration,
            description: String::new(),
            start: Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap(),
            stop: stopped.then_some(Utc.timestamp_opt(1, 0).unwrap()),
            duration,
            billable,
            workspace_id: 1,
            tags: Vec::new(),
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn invoice_rule_rounds_up_and_applies_minimum_per_entry() {
        assert_eq!(invoice_seconds(0), 1800);
        assert_eq!(invoice_seconds(1), 1800);
        assert_eq!(invoice_seconds(900), 1800);
        assert_eq!(invoice_seconds(1800), 1800);
        assert_eq!(invoice_seconds(1801), 2700);
    }

    #[test]
    fn totals_filter_entries_and_group_by_utc_start_month() {
        let entries = vec![
            entry("2026-02-01T00:00:00Z", 901, true, true),
            entry("2026-01-31T23:59:59Z", 900, true, true),
            entry("2026-02-02T00:00:00Z", 900, false, true),
            entry("2026-02-03T00:00:00Z", 900, true, false),
        ];

        let totals = monthly_totals(&entries);
        assert_eq!(totals.get("2026-01"), Some(&1800));
        assert_eq!(totals.get("2026-02"), Some(&1800));
        assert_eq!(
            totals.keys().collect::<Vec<_>>(),
            vec!["2026-01", "2026-02"]
        );
    }

    #[test]
    fn empty_totals_are_supported() {
        assert!(monthly_totals(&[]).is_empty());
    }
